/** Source: link_rfu_2.c → Task_PlayerExchangeUpdate */
export const Task_PlayerExchangeUpdate: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  let i = 0;
      let playerBlock: any = null;
      let sio: any = null;
      let playerId = gRfu.linkPlayerIdx[sSlotToLinkPlayerTableId[gRfu.incomingChild]];
      if (gRfu.status == RFU_STATUS_FATAL_ERROR || gRfu.status == RFU_STATUS_CONNECTION_ERROR)
      {
          gRfu.playerExchangeActive = false;
          rt.DestroyTask(taskId);
      }
      switch (task.data[0])
      {
      case 0:
          if (gSendCmd[0] == 0)
          {
              ResetBlockReceivedFlag(playerId);
              RfuPrepareSendBuffer(RFUCMD_SEND_PLAYER_IDS_NEW);
              task.data[0]++;
          }
          break;
      case 1:
          if (gSendCmd[0] == 0)
              task.data[0]++;
          break;
      case 2:
          if ((GetBlockReceivedStatus() >> playerId) & 1)
          {
              ResetBlockReceivedFlag(playerId);
              playerBlock = gBlockRecvBuffer[playerId];
              gLinkPlayers[playerId] = playerBlock.linkPlayer;
              ConvertLinkPlayerName(gLinkPlayers[playerId]);
              task.data[0]++;
          }
          break;
      case 3:
          sio = gBlockSendBuffer;
          memcpy(sio.magic, sASCII_PokemonSioInfo, ((sASCII_PokemonSioInfo)?.length ?? 32));
          sio.playerCount = gRfu.playerCount;
          for (i = 0; i < RFU_CHILD_MAX; i++)
              sio.linkPlayerIdx[i] = gRfu.linkPlayerIdx[i];
          memcpy(sio.linkPlayers, gLinkPlayers, ((gLinkPlayers)?.length ?? 32));
          task.data[0]++;
           
      case 4:
          sio = gBlockSendBuffer;
          sio.playerCount = gRfu.playerCount;
          for (i = 0; i < RFU_CHILD_MAX; i++)
              sio.linkPlayerIdx[i] = gRfu.linkPlayerIdx[i];
          memcpy(sio.linkPlayers, gLinkPlayers, ((gLinkPlayers)?.length ?? 32));
           
          if (SendBlock(0, gBlockSendBuffer, /* offsetof */ 0))
              task.data[0]++;
          break;
      case 5:
          if (IsLinkTaskFinished() && GetBlockReceivedStatus() & 1)
          {
              CpuFill16(0, gBlockRecvBuffer, 0);
              ResetBlockReceivedFlag(0);
              gRfu.playerExchangeActive = false;
              if (gRfu.newChildQueue)
              {
                  for (i = 0; i < RFU_CHILD_MAX; i++)
                  {
                      if ((gRfu.newChildQueue >> i) & 1)
                      {
                          gRfu.nextChildBits = 1 << i;
                          gRfu.newChildQueue ^= (1 << i);
                          gRfu.playerExchangeActive = true;
                          break;
                      }
                  }
              }
              rt.DestroyTask(taskId);
          }
          break;
      }
};

/** Source: link_rfu_2.c → Task_PlayerExchangeChat */
export const Task_PlayerExchangeChat: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  if (gRfu.status == RFU_STATUS_FATAL_ERROR || gRfu.status == RFU_STATUS_CONNECTION_ERROR)
          rt.DestroyTask(taskId);
      switch (task.data[0])
      {
      case 0:
          if (gRfu.playerCount)
          {
              LocalLinkPlayerToBlock();
              SendBlock(0, gBlockSendBuffer, 0);
              task.data[0]++;
          }
          break;
      case 1:
          if (IsLinkTaskFinished())
              task.data[0]++;
          break;
      case 2:
          if (GetBlockReceivedStatus() & 1)
          {
              ReceiveRfuLinkPlayers(gBlockRecvBuffer);
              ResetBlockReceivedFlag(0);
              gReceivedRemoteLinkPlayers = 1;
              rt.DestroyTask(taskId);
          }
          break;
      }
};

/** Source: link_rfu_2.c → Task_SendDisconnectCommand */
export const Task_SendDisconnectCommand: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  if (gSendCmd[0] == 0 && !gRfu.playerExchangeActive)
      {
          RfuPrepareSendBuffer(RFUCMD_DISCONNECT);
          gSendCmd[1] = task.data[0];
          gSendCmd[2] = task.data[1];
          gRfu.playerCount -= sPlayerBitsToCount[task.data[0]];
          gSendCmd[3] = gRfu.playerCount;
          rt.DestroyTask(taskId);
      }
};

/** Source: link_rfu_2.c → Task_RfuReconnectWithParent */
export const Task_RfuReconnectWithParent: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  const data = task.data;

      if (CanTryReconnectParent())
      {
          let id = GetPartnerIndexByNameAndTrainerID(data, ReadU16(data[8]));
          if (id != 0xFF)
          {
              if (gRfuLinkStatus.partner[id].slot != 0xFF)
              {
                  gRfu.reconnectParentId = id;
                  if (TryReconnectParent())
                      rt.DestroyTask(taskId);
              }
              else if (GetHostRfuGameData().activity == ACTIVITY_WONDER_CARD
                    || GetHostRfuGameData().activity == ACTIVITY_WONDER_NEWS)
              {
                  data[0]++;
              }
              else
              {
                   
                  RfuSetStatus(RFU_STATUS_CONNECTION_ERROR, F_RFU_ERROR_5 | F_RFU_ERROR_6 | F_RFU_ERROR_7);
                  rt.DestroyTask(taskId);
              }
          }
          else
          {
              data[0]++;
              gRfu.reconnectParentId = id;
          }
      }
      else
      {
          data[0]++;
      }

      if (data[0] > 240)
      {
           
          RfuSetStatus(RFU_STATUS_CONNECTION_ERROR, F_RFU_ERROR_5 | F_RFU_ERROR_6 | F_RFU_ERROR_7);
          rt.DestroyTask(taskId);
      }
};

/** Source: link_rfu_2.c → Task_TryConnectToUnionRoomParent */
export const Task_TryConnectToUnionRoomParent: TaskCallback = (task, rt) => {
  const taskId = task.taskId;
  if (gRfu.status == RFU_STATUS_NEW_CHILD_DETECTED)
          rt.DestroyTask(taskId);

      if (++task.data[0] > 300)
      {
           
          RfuSetStatus(RFU_STATUS_CONNECTION_ERROR, F_RFU_ERROR_5 | F_RFU_ERROR_6 | F_RFU_ERROR_7);
          rt.DestroyTask(taskId);
      }

       
      if (gRfu.parentId != 0 && lman.parent_child == MODE_CHILD)
      {
           
          let trainerId = ReadU16(gRfu.parent.compatibility.playerTrainerId);
          let id = GetPartnerIndexByNameAndTrainerID(gRfu.parentName, trainerId);
          if (id != 0xFF)
          {
               
              if (!IsPartnerActivityIncompatible(task.data[1], gRfuLinkStatus.partner[id].gname))
              {
                  if (gRfuLinkStatus.partner[id].slot != 0xFF && !rfu_LMAN_CHILD_connectParent(gRfuLinkStatus.partner[id].id, 90))
                  {
                       
                      gRfu.state = RFUSTATE_CONNECTED;
                      rt.DestroyTask(taskId);
                  }
              }
              else
              {
                   
                  RfuSetStatus(RFU_STATUS_CONNECTION_ERROR, F_RFU_ERROR_5 | F_RFU_ERROR_6 | F_RFU_ERROR_7);
                  rt.DestroyTask(taskId);
              }
          }
      }
};

